      "most_likely_effort": 1
    },
    {
      "activity_id": "A23",
      "activity_name": "U6 - Modify deployment code",
      "activity_description": "Update module deployment logic to inject module id and container id into the component's context.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A24",
      "activity_name": "U6 - Update component API",
      "activity_description": "Modify base component classes (source, processor, sink) to provide access to module id and container id.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A25",
      "activity_name": "U6 - Update logging in components",
      "activity_description": "Enhance logging in sample components to include module id and container id as a demonstration.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A26",
      "activity_name": "U6 - Testing",
      "activity_description": "Test that module id and container id are correctly available in components and appear in logs.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A27",
      "activity_name": "U7 - Identify current Kafka bus config",
      "activity_name": "U7 - Identify current Kafka bus config",
      "activity_description": "Review existing Kafka consumer and producer configuration classes to understand current defaults.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A28",
      "activity_name": "U7 - Add new configuration properties",
      "activity_description": "Define new properties for consumers (autoCommitEnabled, queueSize, maxWait, fetchSize) and producers (batchSize, batchTimeout) in configuration classes.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A29",
      "activity_name": "U7 - Implement property binding and factory changes",
      "activity_description": "Bind new properties to Kafka consumer/producer factories and ensure they override defaults.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A30",
      "activity_name": "U7 - Update documentation",
      "activity_description": "Document the new Kafka bus configuration properties in reference guide.",
